  FT["PH-H7296"] = {"id":"PH-H7296","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8828_2000.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"将卡林加省 Pinukpuk 市镇 Allaguia 中学从 Tabuk 市镇该校分离并改设为独立的 Allaguia 国立中学并拨款","en":"An Act Separating the Allaguia Barangay High School Also Known as Doña Eufronia M. Puzon Memorial High School - Allaguia Annex in the Municipality of Pinukpuk, Province of Kalinga From the Doña Eufronia M. Puzon Memorial High School in the Municipality of Tabuk, and Converting It Into An Independent National High School to Be Known as the Allaguia National High School and Appropriating Funds Therefor","orig":"An Act Separating the Allaguia Barangay High School Also Known as Doña Eufronia M. Puzon Memorial High School - Allaguia Annex in the Municipality of Pinukpuk, Province of Kalinga From the Doña Eufronia M. Puzon Memorial High School in the Municipality of Tabuk, and Converting It Into An Independent National High School to Be Known as the Allaguia National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8828","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8828_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7296-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Allaguia Barangay High School also known as Doña Eufronia M. Puzon Memorial High School -Allaguia Annex in the Municipality of Pinukpuk, Province of Kalinga, is hereby separated from the Doña Eufronia M. Puzon Memorial High School in the Municipality of Tabuk and converted into a separate and independent national high school to be known as the Allaguia National High School."}},{"id":"PH-H7296-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The school shall offer secondary education proper as well as secondary science courses to carry out its objectives as may be authorized by the Secretary of the Department of Education, Culture and Sports."}},{"id":"PH-H7296-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Department of Education, Culture and Sports shall issue rules and regulations as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H7296-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All personnel, assets, liabilities and records of the Allaguia Barangay High School are hereby transferred to and absorbed by the Allaguia National High School."}},{"id":"PH-H7296-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Doña Eufronia M. Puzon Memorial High School - Allaguia Annex. Thereafter, such sums as may be necessary for the operation and maintenance of the Allaguia National High School shall be included in the annual General Appropriations Act."}},{"id":"PH-H7296-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p104","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Allaguia Barangay High School Also Known as Doña Eufronia M. Puzon Memorial High School - Allaguia Annex in the Municipality of Pinukpuk, Province of Kalinga From the Doña Eufronia M. Puzon Memorial High School in the Municipality of Tabuk, and Converting It Into An Independent National High School to Be Known as the Allaguia National High School and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H7297"] = {"id":"PH-H7297","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8829_2000.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Taytay市","en":"An Act Converting the Calawag Barangay High School in Barangay Calawag, Municipality of Taytay, Province of Palawan, Into a National High School to Be Known as Calawag National High School, Providing for Its Funding and for Other Purposes","orig":"An Act Converting the Calawag Barangay High School in Barangay Calawag, Municipality of Taytay, Province of Palawan, Into a National High School to Be Known as Calawag National High School, Providing for Its Funding and for Other Purposes"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8829","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8829_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7297-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Calawag Barangay High School in Barangay Calawag, Municipality of Taytay, Province of Palawan, is hereby converted into a national high school to be known as the Calawag National High School."}},{"id":"PH-H7297-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All assets, immovable and movable, and records of the Calawag Barangay High School, as well as its liabilities or obligations, are hereby transferred to the Calawag National High School: Provided, however, That the positions, rights and security of tenure of academic and nonacademic personnel who choose to remain and serve in the new school shall not be impaired."}},{"id":"PH-H7297-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H7297-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Department of Education, Culture and Sports shall promulgate the necessary rules and regulations for the effective implementation of the provisions of this Act."}},{"id":"PH-H7297-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p104"};
